"""Dependency-free, ingress-safe operator dashboard."""

from __future__ import annotations


# Keep this page static: values are fetched from same-origin APIs and inserted
# with textContent. This makes a malformed profile or diagnostic event inert.
_DASHBOARD = r'''<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<meta http-equiv="Content-Security-Policy" content="default-src 'none'; connect-src 'self'; style-src 'unsafe-inline'; script-src 'unsafe-inline'; img-src 'self' data:;">
<title>HA Switchboard</title>
<style>
:root{color-scheme:dark;--panel:#151c26;--line:#293548;--text:#e6edf3;--muted:#9aa8b8;--accent:#72b7ff;--good:#53d397;--warn:#f2bf5a;--bad:#ff7b72}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 10% 0%,#192a40 0,#0d1117 42%);color:var(--text);font:15px/1.5 system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}main{max-width:1180px;margin:auto;padding:32px 20px 56px}header{display:flex;justify-content:space-between;gap:20px;align-items:flex-start;margin-bottom:24px}h1,h2,h3,p{margin:0}h1{font-size:clamp(1.8rem,4vw,2.7rem);letter-spacing:-.04em}h2{font-size:1rem;margin-bottom:14px}.eyebrow{color:var(--accent);font-weight:700;text-transform:uppercase;letter-spacing:.12em;font-size:.72rem;margin-bottom:6px}.lede{color:var(--muted);margin-top:8px;max-width:720px}button,.link{border:1px solid #41678e;border-radius:8px;background:#1b3855;color:var(--text);cursor:pointer;font:inherit;padding:9px 14px;text-decoration:none;display:inline-block}button:hover,button:focus-visible,.link:hover,.link:focus-visible{background:#264e75;outline:2px solid var(--accent);outline-offset:2px}button:disabled{cursor:wait;opacity:.6}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.card{background:color-mix(in srgb,var(--panel) 92%,transparent);border:1px solid var(--line);border-radius:14px;padding:20px;box-shadow:0 10px 30px #0002}.wide{grid-column:1/-1}.metric{display:flex;justify-content:space-between;gap:15px;padding:10px 0;border-bottom:1px solid var(--line)}.metric:last-child{border-bottom:0}.label{color:var(--muted)}.value{text-align:right;font-weight:650;overflow-wrap:anywhere}.pill{display:inline-flex;align-items:center;gap:7px;border-radius:999px;padding:3px 10px;font-size:.82rem;font-weight:700}.pill:before{content:"";width:7px;height:7px;border-radius:50%;background:currentColor}.ok{color:var(--good);background:#153d30}.degraded,.stale,.loading{color:var(--warn);background:#493718}.disabled,.error{color:var(--bad);background:#4b211f}.sections,.actions{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:9px}.section{border:1px solid var(--line);border-radius:9px;padding:10px 12px}.section strong{display:block;font-size:.9rem}.section span{color:var(--muted);font-size:.8rem}.empty,.foot{color:var(--muted)}.foot{font-size:.82rem;margin-top:18px}.intro{margin-bottom:18px}.diagnostics{max-height:360px;overflow:auto;border:1px solid var(--line);border-radius:8px}.event{padding:10px 12px;border-bottom:1px solid var(--line)}.event:last-child{border-bottom:0}.event time,.event small{color:var(--muted)}.event strong{margin:0 6px}.filters{display:flex;flex-wrap:wrap;gap:9px;align-items:end;margin-bottom:12px}label{color:var(--muted);font-size:.85rem}select,input{display:block;min-height:38px;margin-top:4px;border:1px solid var(--line);border-radius:7px;padding:7px 9px;background:#0d1117;color:var(--text);font:inherit}@media(prefers-reduced-motion:reduce){*,*::before,*::after{scroll-behavior:auto!important;transition:none!important;animation:none!important}}@media(max-width:700px){main{padding:22px 14px 40px}header{flex-direction:column}.grid{grid-template-columns:1fr}.wide{grid-column:auto}.metric{align-items:flex-start}}
</style></head>
<body><main>
<header><div><div class="eyebrow">Home Assistant App</div><h1 id="dashboard-title">HA Switchboard</h1><p class="lede">A local-first view of gateway health, the sanitized Home Assistant profile, provider readiness, and recoverable diagnostics.</p></div><div class="actions"><button id="refresh" type="button">Refresh status</button><button id="scan" type="button">Scan Home Assistant now</button></div></header>
<div id="page-status" class="foot" role="status" aria-live="polite">Loading dashboard…</div>
<div class="grid" aria-live="polite">
<section class="card"><h2>Gateway health</h2><div class="metric"><span class="label">Liveness</span><span id="health" class="value">Loading…</span></div><div class="metric"><span class="label">Readiness</span><span id="ready" class="value">Loading…</span></div><div class="metric"><span class="label">Decision service</span><span id="jev" class="value">Loading…</span></div><div class="metric"><span class="label">Gateway authentication</span><span id="gatewayAuth" class="value">Loading…</span></div></section>
<section class="card"><h2>App configuration</h2><div class="metric"><span class="label">Version</span><span id="version" class="value">Loading…</span></div><div class="metric"><span class="label">Configuration status</span><span id="configStatus" class="value">Loading…</span></div><div class="metric"><span class="label">Gateway mode</span><span id="gatewayMode" class="value">Loading…</span></div><div class="metric"><span class="label">Web UI access</span><span id="ingress" class="value">Loading…</span></div><div class="metric"><span class="label">Privacy mode</span><span id="privacy" class="value">Loading…</span></div><div class="metric"><span class="label">Fallback route</span><span id="fallback" class="value">Loading…</span></div><div class="metric"><span class="label">Profile refresh</span><span id="refreshMinutes" class="value">Loading…</span></div></section>
<section class="card"><h2>Home Assistant integration</h2><p id="integrationSummary" class="lede intro">Checking the latest profile…</p><div class="metric"><span class="label">Profile state</span><span id="profileState" class="value">Loading…</span></div><div class="metric"><span class="label">Profile revision</span><span id="profileRevision" class="value">—</span></div><div class="metric"><span class="label">Profile warning</span><span id="profileWarning" class="value">—</span></div><div class="metric"><span class="label">Capabilities exposed</span><span id="capabilities" class="value">—</span></div><div class="metric"><span class="label">Last reconciled</span><span id="reconciled" class="value">—</span></div><p class="foot intro">In Home Assistant, open Settings → Voice assistants and select HA Switchboard as the Conversation agent. The gateway cannot see which pipeline is selected.</p><div class="actions"><a class="link" href="/config/integrations" target="_top">Manage integration</a><a class="link" href="/config/voice-assistants" target="_top">Configure Assist</a></div></section>
<section class="card"><h2>Profile and scan</h2><div class="metric"><span class="label">Adapter connection</span><span id="connected" class="value">—</span></div><div class="metric"><span class="label">Scan state</span><span id="scan-state" class="value">Idle</span></div><div class="metric"><span class="label">Pending sections</span><span id="pending" class="value">—</span></div><div class="metric"><span class="label">Pending reason</span><span id="pendingReason" class="value">—</span></div><div class="metric"><span class="label">Last source event</span><span id="event" class="value">—</span></div><p id="message" class="foot" role="status">Checking gateway status…</p></section>
<section class="card wide"><h2>Provider state</h2><p class="lede intro">Provider cards show compatibility and reachability only. Endpoint URLs, model credentials, request text, and raw provider responses are never displayed.</p><div id="providers" class="sections"><p class="empty">Loading provider state…</p></div></section>
<section class="card wide"><h2>Profile sections</h2><p class="foot intro">These are redacted freshness signals. Entities, IDs, states, and service payloads are intentionally absent.</p><div id="sections" class="sections"><p class="empty">Loading section freshness…</p></div></section>
<section class="card wide"><h2>Diagnostics</h2><p class="lede intro">Recent, redacted gateway events. Use filters to narrow the log; event details never include secrets, provider URLs, or Home Assistant entity IDs.</p><div class="filters"><label>Severity<select id="diagnostic-level" aria-label="Filter diagnostics by severity"><option value="">All severities</option><option>error</option><option>warning</option><option>info</option></select></label><label>Event type<input id="diagnostic-kind" aria-label="Filter diagnostics by event type" maxlength="48" placeholder="All event types"></label><label>Route class<input id="diagnostic-route-class" aria-label="Filter diagnostics by route class" maxlength="48" placeholder="All route classes"></label><label>Outcome<input id="diagnostic-outcome" aria-label="Filter diagnostics by outcome" maxlength="48" placeholder="All outcomes"></label><button id="diagnostic-refresh" type="button">Refresh diagnostics</button><button id="diagnostic-clear" type="button" disabled>Clear filters</button></div><p id="diagnostic-status" class="foot" role="status" aria-live="polite">Loading diagnostics…</p><div id="diagnostics" class="diagnostics" aria-live="polite"><p class="empty" style="padding:12px">Loading diagnostics…</p></div><div class="actions" style="margin-top:12px"><button id="diagnostic-prev" type="button" disabled>Previous page</button><button id="diagnostic-next" type="button" disabled>Next page</button></div></section>
<section class="card wide"><h2>Configuration and recovery</h2><p class="lede">App options are managed by Home Assistant Supervisor. The Core integration stores its gateway connection in Home Assistant. After changing either, refresh this page. If the profile is stale, confirm the Core integration is running, then request one scan and wait for the scan state to settle.</p><div class="actions"><a class="link" href="/config" target="_top">Open Home Assistant settings</a><a class="link" href="/config/integrations/dashboard" target="_top">View integrations</a></div></section>
</div><p class="foot">Switchboard does not execute Home Assistant services from this page. It never displays secrets or raw utterances.</p>
</main>
<script>
(()=>{
  'use strict';
  const POLL_MS=1500,MAX_POLLS=20,PAGE_SIZE=20,MAX_TEXT=160;
  const el=id=>document.getElementById(id);
  const api=path=>{const base=window.location.pathname.endsWith('/')?window.location.pathname:window.location.pathname+'/';return new URL(path,new URL(base,window.location.origin)).toString()};
  const safeText=(value,fallback='Not available',limit=MAX_TEXT)=>{const text=String(value??'').replace(/[\u0000-\u001f\u007f]/g,' ').replace(/\s+/g,' ').trim().slice(0,limit);return text||fallback};
  const humanize=value=>{const text=safeText(value,'Unknown',96).replace(/[_-]+/g,' ').replace(/\s+/g,' ').trim();return text?text.charAt(0).toUpperCase()+text.slice(1):'Unknown'};
  const cls=value=>['ok','ready','active','connected','available','configured','complete','succeeded','healthy'].includes(String(value).toLowerCase())?'ok':['degraded','stale','queued','running','loading','unknown','unavailable','waiting','cooldown'].includes(String(value).toLowerCase())?'degraded':'disabled';
  const text=(id,value,format=safeText)=>{el(id).textContent=format(value)};
  const pill=(id,label,status)=>{const node=el(id);node.textContent='';const item=document.createElement('span');item.className=`pill ${cls(status)}`;item.textContent=safeText(label);node.appendChild(item)};
  const time=value=>{if(!value)return 'Not available';const date=new Date(value);return Number.isNaN(date.getTime())?'Not available':date.toLocaleString()};
  const pairs=value=>value&&typeof value==='object'&&!Array.isArray(value)?Object.entries(value):[];
  const pending=(body)=>{const monitor=body&&body.monitor&&typeof body.monitor==='object'?body.monitor:{};const sections=Array.isArray(monitor.pending_sections)?monitor.pending_sections:[];const invalidations=Array.isArray(monitor.pending_invalidations)?monitor.pending_invalidations:[];return {monitor,sections,invalidations}};
  const profileComplete=body=>{const state=String(body?.status||'').toLowerCase();const waits=pending(body);return state==='active'&&!waits.sections.length&&!waits.invalidations.length};
  const failure=(kind,status)=>({kind,status});
  const failureKind=status=>status===401||status===403?'unauthorized':status===404||status===503?'unavailable':status>=500?'server-error':'unavailable';
  const normalizeFailure=error=>error&&error.kind?error:failure('network');
  const failureMessage=(error,subject='gateway')=>{const kind=normalizeFailure(error).kind;if(kind==='unauthorized')return `${subject} access is not authorized.`;if(kind==='unavailable')return `${subject} is unavailable right now.`;if(kind==='server-error')return `${subject} returned a server error.`;return `The ${subject} could not be reached. Check the App state and try again.`};
  const json=async(path,options)=>{let response;try{response=await fetch(api(path),options)}catch(_){throw failure('network')}let body={};try{body=await response.json()}catch(_){}if(!response.ok&&response.status!==503)throw failure(failureKind(response.status),response.status);return {response,body}};
  const optionalJson=async(path)=>{try{const result=await json(path);if(!result.response.ok)throw failure(failureKind(result.response.status),result.response.status);return {value:result}}catch(error){return {error:normalizeFailure(error)}}};
  function renderSections(value){const target=el('sections');target.textContent='';const rows=pairs(value);if(!rows.length){const empty=document.createElement('p');empty.className='empty';empty.textContent='No profile has been reconciled yet.';target.appendChild(empty);return}rows.forEach(([name,item])=>{const card=document.createElement('div');card.className='section';const title=document.createElement('strong');title.textContent=humanize(name);const state=document.createElement('span');state.textContent=humanize(item&&item.status?item.status:'unknown');card.append(title,state);target.appendChild(card)})}
  function renderProviders(value,app,ready){const target=el('providers');target.textContent='';const source=pairs(value);if(!source.length){source.push(['Jev',{status:ready.jev_configured?'configured':'disabled',detail:ready.jev_configured?'Configured; compatibility not verified':'Not configured'}]);source.push(['Fallback',{status:app.fallback_configured?'configured':'disabled',detail:app.fallback_configured?'Configured; reachability not verified':'Disabled'}])}source.forEach(([name,item])=>{item=item&&typeof item==='object'?item:{status:item};const card=document.createElement('div');card.className='section';const title=document.createElement('strong');title.textContent=humanize(name);const state=document.createElement('span');const detail=item.detail||item.message;state.textContent=detail?safeText(detail):humanize(item.status||'unknown');card.append(title,state);target.appendChild(card)})}
  function renderProviderFailure(error){const target=el('providers');target.textContent='';const empty=document.createElement('p');empty.className='empty';empty.textContent=`Provider status ${failureMessage(error,'status').toLowerCase()}`;target.appendChild(empty)}
  function renderConfig(app){const warnings=Array.isArray(app.configuration_warnings)?app.configuration_warnings:[];text('configStatus',warnings.length?`Needs attention: ${humanize(warnings[0])}`:'Configured');}
  let scanPolls=0,scanTimer=null,diagnosticPage=1,diagnosticTotal=0;
  function setScanState(value){const state=String(value||'idle');pill('scan-state',humanize(state),state)}
  async function refresh(){text('page-status','Refreshing dashboard…');try{const results=await Promise.all([json('healthz'),json('readyz'),json('v1/profile/status'),json('v1/app/status'),optionalJson('v1/provider/status')]);const[health,ready,profile,app,providerResult]=results.map(item=>item.body||item.value?.body);const providerError=results[4].error;pill('health',health.status==='ok'?'Operational':'Unavailable',health.status);pill('ready',ready.status==='ready'?'Ready':'Needs attention',ready.status);text('jev',ready.jev_configured?'Configured; compatibility unverified':'Not configured');text('gatewayAuth',app.auth_configured?'Token configured':'No token configured');text('version',app.version);renderConfig(app);text('gatewayMode',app.gateway_mode,'humanize');text('ingress',app.ingress_only?'Supervisor ingress only':'Standalone/direct mode');text('privacy',app.privacy_mode,'humanize');text('refreshMinutes',`${safeText(app.profile_refresh_minutes,15)} minutes`);text('fallback',app.fallback_configured?`${humanize(app.fallback_provider||'configured')} (reachability unverified)`:'Not configured');pill('profileState',humanize(profile.status),profile.status);text('profileRevision',profile.profile_revision);const warningValues=[...(Array.isArray(profile.warnings)?profile.warnings:[]),...(Array.isArray(app.configuration_warnings)?app.configuration_warnings:[])];text('profileWarning',warningValues.length?humanize(warningValues[0]):'None');text('capabilities',profile.capability_count, safeText);text('reconciled',time(profile.last_reconciled_at));const waits=pending(profile);pill('connected',waits.monitor.connected?'Connected':'Not connected',waits.monitor.connected?'connected':'disabled');text('pending',waits.sections.length?waits.sections.map(humanize).join(', '):'None');text('pendingReason',waits.invalidations.length?waits.invalidations.map(humanize).join(', '):'None');text('event',time(waits.monitor.last_event_at));renderSections(profile.sections);if(providerError)renderProviderFailure(providerError);else renderProviders(provider.providers||provider,app,ready);text('integrationSummary',profileComplete(profile)?'The Core integration supplied a current profile.':'The gateway is running, but the profile still has pending work.');text('message',profileComplete(profile)&&ready.status==='ready'?'The profile is ready. Assist pipeline selection and provider compatibility are separate checks.':'The gateway is running but the profile needs attention before control requests can proceed.');text('page-status',providerError?'Dashboard updated; provider status is unavailable.':'Dashboard updated.')}catch(error){const message=failureMessage(error,'Gateway status');['health','ready','profileState','connected'].forEach(id=>pill(id,'Unavailable','error'));text('message',message);text('page-status',message)}}
  async function pollScan(){if(scanPolls++>=MAX_POLLS){setScanState('timeout');text('message','Scan status polling timed out; the last known profile was preserved. Check diagnostics.');el('scan').disabled=false;return}try{const result=await json('v1/profile/status');const waits=pending(result.body);if(profileComplete(result.body)){setScanState('complete');el('scan').disabled=false;refresh();return}const rawState=waits.sections.length||waits.invalidations.length?'waiting':result.body.monitor?.scan_status||result.body.scan_status||result.body.status;setScanState(rawState);if(!['error','failed','disabled'].includes(String(rawState).toLowerCase()))scanTimer=window.setTimeout(pollScan,POLL_MS);else{el('scan').disabled=false;text('message','Scan did not complete. Check the profile warning and diagnostics.')}}catch(error){setScanState('error');el('scan').disabled=false;text('message',failureMessage(error,'Scan status'))}}
  async function scan(){if(scanTimer)window.clearTimeout(scanTimer);scanPolls=0;el('scan').disabled=true;setScanState('queued');text('message','Requesting a new Home Assistant scan…');try{const result=await json('v1/profile/scan',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});if(result.response.status!==202)throw failure(failureKind(result.response.status),result.response.status);text('message','Scan queued. Waiting for an active profile with no pending sections or invalidations…');scanTimer=window.setTimeout(pollScan,POLL_MS)}catch(error){setScanState('error');text('message',failureMessage(error,'Scan request'));el('scan').disabled=false}}
  const diagnosticFilterIds=['diagnostic-level','diagnostic-kind','diagnostic-route-class','diagnostic-outcome'];
  const diagnosticFiltersActive=()=>diagnosticFilterIds.some(id=>el(id).value.trim());
  const updateDiagnosticControls=()=>{el('diagnostic-clear').disabled=!diagnosticFiltersActive();};
  async function diagnostics(){const target=el('diagnostics');const status=el('diagnostic-status');target.textContent='Loading diagnostics…';status.textContent='Loading diagnostics…';const params=new URLSearchParams({page:String(diagnosticPage),limit:String(PAGE_SIZE)});const filters=[['level','diagnostic-level'],['event_type','diagnostic-kind'],['route_class','diagnostic-route-class'],['outcome','diagnostic-outcome']];filters.forEach(([key,id])=>{const value=el(id).value.trim();if(value)params.set(key,value)});updateDiagnosticControls();try{const result=await json(`v1/diagnostics?${params}`);if(!result.response.ok)throw failure(failureKind(result.response.status),result.response.status);const body=result.body,rows=Array.isArray(body.events)?body.events:Array.isArray(body.items)?body.items:[];diagnosticTotal=Number.isFinite(Number(body.total))?Number(body.total):rows.length;const first=rows.length?(diagnosticPage-1)*PAGE_SIZE+1:0;const last=(diagnosticPage-1)*PAGE_SIZE+rows.length;status.textContent=`Showing ${first}–${last} of ${diagnosticTotal} diagnostic events.`;target.textContent='';if(!rows.length){const empty=document.createElement('p');empty.className='empty';empty.style.padding='12px';empty.textContent=diagnosticFiltersActive()?'No diagnostics match these filters.':'No diagnostics have been recorded yet.';target.appendChild(empty)}rows.forEach(item=>{const row=document.createElement('article');row.className='event';const timeNode=document.createElement('time');timeNode.textContent=time(item.occurred_at||item.timestamp||item.created_at);const strong=document.createElement('strong');strong.textContent=humanize(item.level||item.severity||'info');const summary=document.createElement('span');summary.textContent=item.summary?safeText(item.summary):humanize(item.message||item.event_type||'Diagnostic event');const meta=document.createElement('small');const correlation=item.correlation_id?`Correlation ${safeText(item.correlation_id,'',48)}`:'';const route=item.route_class?`Route ${humanize(item.route_class)}`:'';const outcome=item.outcome?`Outcome ${humanize(item.outcome)}`:'';meta.textContent=[correlation,route,outcome].filter(Boolean).join(' · ');row.append(timeNode,strong,summary,meta);target.appendChild(row)});el('diagnostic-prev').disabled=diagnosticPage<=1;el('diagnostic-next').disabled=rows.length<PAGE_SIZE||diagnosticPage*PAGE_SIZE>=diagnosticTotal}catch(error){const message=failureMessage(error,'Diagnostics');status.textContent=message;target.textContent='';const empty=document.createElement('p');empty.className='empty';empty.style.padding='12px';empty.textContent=message;target.appendChild(empty);el('diagnostic-prev').disabled=true;el('diagnostic-next').disabled=true}}
  el('refresh').addEventListener('click',refresh);el('scan').addEventListener('click',scan);el('diagnostic-refresh').addEventListener('click',()=>{diagnosticPage=1;diagnostics()});el('diagnostic-clear').addEventListener('click',()=>{diagnosticFilterIds.forEach(id=>{el(id).value=''});diagnosticPage=1;diagnostics()});diagnosticFilterIds.forEach(id=>el(id).addEventListener('change',()=>{diagnosticPage=1;diagnostics()}));el('diagnostic-prev').addEventListener('click',()=>{if(diagnosticPage>1){diagnosticPage--;diagnostics()}});el('diagnostic-next').addEventListener('click',()=>{diagnosticPage++;diagnostics()});refresh();diagnostics();
})();
</script></body></html>
'''


def dashboard_html() -> bytes:
    """Return the static dashboard without runtime configuration values."""

    accessibility = r'''<a class="skip-link" href="#dashboard-content">Skip to dashboard content</a><script>const main=document.querySelector('main');if(main){main.id='dashboard-content';main.setAttribute('aria-labelledby','dashboard-title')}const actions=document.querySelector('header .actions');if(actions){actions.setAttribute('role','navigation');actions.setAttribute('aria-label','Dashboard actions')}</script><style>
.skip-link{position:absolute;left:8px;top:8px;z-index:10;padding:8px 12px;background:#1b3855;color:var(--text);transform:translateY(-150%)}.skip-link:focus{transform:translateY(0);outline:2px solid var(--accent);outline-offset:2px}
</style><script>document.getElementById('page-status')?.setAttribute('aria-atomic','true');
(()=>{const q=id=>document.getElementById(id);const set=(id,name,value)=>q(id)?.setAttribute(name,String(value));const announce=value=>{const node=q('page-status');if(node)node.textContent=value};const busy=(id,value)=>set(id,'aria-busy',value);const disabled=(id,value)=>{const node=q(id);if(node){node.disabled=value;set(id,'aria-disabled',value)}};const refresh=q('refresh'),scan=q('scan'),diag=q('diagnostic-refresh'),prev=q('diagnostic-prev'),next=q('diagnostic-next'),dashboard=q('page-status'),events=q('diagnostics');if(refresh)refresh.setAttribute('aria-controls','page-status');if(scan)scan.setAttribute('aria-controls','scan-state message');if(diag)diag.setAttribute('aria-controls','diagnostics');if(events){events.setAttribute('role','log');events.setAttribute('aria-label','Diagnostic events');events.setAttribute('aria-atomic','false')}[prev,next].forEach(node=>{if(node){node.setAttribute('aria-controls','diagnostics');node.setAttribute('aria-disabled',String(node.disabled))}});const observe=(node,label)=>{if(!node)return;new MutationObserver(()=>{if(node.disabled)set(node.id,'aria-disabled',true)}).observe(node,{attributes:true,attributeFilter:['disabled']});node.addEventListener('click',()=>{busy(node.id==='diagnostic-refresh'?'diagnostics':'page-status',true);announce(label)})};observe(refresh,'Refreshing dashboard…');observe(scan,'Requesting a new Home Assistant scan…');observe(diag,'Refreshing diagnostics…');observe(prev,'Loading previous diagnostics page…');observe(next,'Loading next diagnostics page…');new MutationObserver(()=>{if(dashboard)busy('page-status',false);if(events)busy('diagnostics',false)}).observe(document.body,{childList:true,subtree:true});})();
</script>'''
    page = _DASHBOARD.replace('</body>', accessibility + '</body>')
    return page.encode("utf-8")
